'use client';
/* eslint-disable react-hooks/set-state-in-effect */

import { useCallback, useEffect, useMemo, useState, type ReactNode } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { z } from 'zod';
import { BadgeDollarSign, Check, CircleDollarSign, ClipboardCheck, Download, Eye, FileText, Landmark, ListChecks, Pencil, Plus, ReceiptText, RefreshCw, Send, Settings2, Trash2, UsersRound, WalletCards, X } from 'lucide-react';
import { Permission } from '@mym/shared';
import { api } from '@/lib/api';
import { userCanAccess } from '@/lib/admin-permissions';
import { useSession } from '@/components/session-provider';
import { useToast } from '@/components/ui/toast-provider';
import { Button, Input, Modal, PageHeader, Select, Textarea } from '@/components/ui/primitives';
import { TableActionButton } from '@/components/admin/table-action-button';

type Tab = 'summary' | 'attendance' | 'settlements' | 'runs' | 'advances' | 'profiles' | 'concepts' | 'history';
type Named = { _id: string; name?: string; eventName?: string; fullName?: string; firstName?: string; lastName?: string; salonIds?: string[]; managedSalonIds?: string[] };
type Attendance = { _id: string; userId: Named; salonId?: Named; eventId?: Named; startedAt: string; endedAt?: string; workedMinutes?: number; approvedMinutes?: number; payrollStatus: 'pending' | 'approved' | 'rejected'; flags: string[]; status: string; payrollSettlementId?: string };
type Concept = { _id: string; code: string; name: string; type: 'earning' | 'deduction'; source: string; isActive: boolean; isAutomatic: boolean; requiresReason: boolean; displayOrder: number; description?: string };
type Settlement = { _id: string; settlementCode: string; employeeId: Named; periodStart: string; periodEnd: string; status: string; paymentStatus: string; baseAmountMinor: number; earningsAmountMinor: number; grossAmountMinor: number; deductionsAmountMinor: number; netAmountMinor: number; currency: string; items?: SettlementItem[]; attendanceRecordIds?: Attendance[]; receipt?: { secureUrl?: string }; calculationDetails?: { warnings?: string[]; errors?: string[] }; paymentMethod?: string; paymentReference?: string; paidAt?: string };
type SettlementItem = { _id?: string; conceptName: string; conceptType: 'earning' | 'deduction'; quantity: number; unit: string; unitAmountMinor: number; subtotalMinor: number; reason?: string };
type PayrollRun = { _id: string; name: string; periodStart: string; periodEnd: string; status: string; totals: { settlements: number; netAmountMinor: number; paidAmountMinor: number }; salonIds: string[]; employeeIds: string[] };
type Advance = { _id: string; employeeId: Named; date: string; amountMinor: number; currency: string; reason: string; status: string; payrollSettlementId?: string };
type Profile = { _id: string; employeeId: Named; compensationType: string; payrollFrequency: string; hourlyRateMinor?: number; dailyRateMinor?: number; monthlySalaryMinor?: number; eventRateMinor?: number; effectiveFrom: string; effectiveTo?: string; isActive: boolean; version: number; currency: string; salonIds?: Array<string | Named>; notes?: string };
type Dashboard = { withoutProfile: number; incomplete: number; pendingAttendance: number; review: number; unpaid: number; estimatedAmountMinor: number; recent: Settlement[] };
type AuditEntry = { _id: string; action: string; entityType: string; createdAt: string; actorUserId?: Named; metadata?: { reason?: string } };

const tabs: Array<{ id: Tab; label: string; icon: typeof BadgeDollarSign }> = [
  { id: 'summary', label: 'Resumen', icon: BadgeDollarSign }, { id: 'attendance', label: 'Asistencias', icon: ClipboardCheck }, { id: 'settlements', label: 'Liquidaciones', icon: ReceiptText }, { id: 'runs', label: 'Lotes de liquidación', icon: ListChecks }, { id: 'advances', label: 'Adelantos y ajustes', icon: WalletCards }, { id: 'profiles', label: 'Configuración de empleados', icon: Settings2 }, { id: 'concepts', label: 'Conceptos', icon: Landmark }, { id: 'history', label: 'Historial y auditoría', icon: FileText }
];
const statusLabels: Record<string, string> = { draft: 'Borrador', calculated: 'Calculado', under_review: 'En revisión', approved: 'Aprobada', partially_paid: 'Pago parcial', paid: 'Pagada', cancelled: 'Cancelada', pending: 'Pendiente', rejected: 'Rechazada', unpaid: 'Pendiente de pago' };
const compensationLabels: Record<string, string> = { hourly: 'Por hora', daily: 'Por jornada', monthly: 'Mensual', per_event: 'Por evento', mixed: 'Mixto' };
const flagsLabels: Record<string, string> = { incomplete: 'Incompleta', observed: 'Observada', negative_duration: 'Duración inválida', excessive_duration: 'Duración excesiva', overlap: 'Solapada', manually_adjusted: 'Corregida manualmente' };
const money = (value = 0, currency = 'ARS') => new Intl.NumberFormat('es-AR', { style: 'currency', currency, minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(value) / 100);
const person = (value?: Named) => value?.fullName || [value?.firstName, value?.lastName].filter(Boolean).join(' ') || 'Sin asignar';
const date = (value?: string) => value ? new Intl.DateTimeFormat('es-AR', { dateStyle: 'short', timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date(value)) : '—';
const dateTime = (value?: string) => value ? new Intl.DateTimeFormat('es-AR', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date(value)) : '—';
const minutes = (value?: number) => value === undefined ? '—' : `${Math.floor(value / 60)} h ${value % 60} min`;
const apiError = (error: unknown, fallback: string) => error instanceof Error ? error.message : fallback;
const minor = (value: string) => Math.max(0, Math.round(Number(value || 0) * 100));
const todayParts = () => Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date()).map((item) => [item.type, item.value]));
const payrollDateInput = (value?: string | Date) => {
  if (!value) return '';
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date(value)).map((item) => [item.type, item.value]));
  return `${parts.year}-${parts.month}-${parts.day}`;
};
const todayPayrollDate = () => { const parts = todayParts(); return `${parts.year}-${parts.month}-${parts.day}`; };
const currentPeriod = () => { const parts = todayParts(); const last = new Date(Date.UTC(Number(parts.year), Number(parts.month), 0)).getUTCDate(); return { from: `${parts.year}-${parts.month}-01`, to: `${parts.year}-${parts.month}-${String(last).padStart(2, '0')}` }; };
const asPayrollDate = (value: string) => `${value}T12:00:00-03:00`;

function Badge({ value }: { value: string }) {
  const tone = value === 'approved' || value === 'paid' ? 'bg-emerald-100 text-emerald-700' : value === 'rejected' || value === 'cancelled' ? 'bg-red-100 text-red-700' : value === 'under_review' || value === 'partially_paid' ? 'bg-amber-100 text-amber-700' : 'bg-zinc-100 text-zinc-600';
  return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${tone}`}>{statusLabels[value] ?? value}</span>;
}

function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="block text-sm font-medium text-zinc-700"><span className="mb-1.5 block">{label}</span>{children}</label>; }

export function PayrollWorkspace() {
  const { user } = useSession();
  const { showToast } = useToast();
  const router = useRouter();
  const searchParams = useSearchParams();
  const requestedTab = searchParams?.get('tab');
  const requestedEmployeeId = searchParams?.get('employeeId') ?? '';
  const canProfiles = userCanAccess(user, [Permission.PAYROLL_MANAGE_PROFILES, Permission.PAYROLL_MANAGE]);
  const canAttendance = userCanAccess(user, [Permission.PAYROLL_MANAGE_ATTENDANCE, Permission.PAYROLL_MANAGE]);
  const canCreate = userCanAccess(user, [Permission.PAYROLL_CREATE, Permission.PAYROLL_MANAGE]);
  const canCalculate = userCanAccess(user, [Permission.PAYROLL_CALCULATE, Permission.PAYROLL_MANAGE]);
  const canApprove = userCanAccess(user, [Permission.PAYROLL_APPROVE, Permission.PAYROLL_MANAGE]);
  const canPay = userCanAccess(user, [Permission.PAYROLL_PAY, Permission.PAYROLL_MANAGE]);
  const canExport = userCanAccess(user, [Permission.PAYROLL_EXPORT, Permission.PAYROLL_MANAGE]);
  const canAudit = userCanAccess(user, [Permission.PAYROLL_AUDIT, Permission.PAYROLL_MANAGE]);
  const initialPeriod = useMemo(() => currentPeriod(), []);
  const [tab, setTab] = useState<Tab>(() => tabs.some((item) => item.id === requestedTab) ? requestedTab as Tab : 'summary');
  const [period, setPeriod] = useState(initialPeriod);
  const [loading, setLoading] = useState(false);
  const [acting, setActing] = useState(false);
  const [dashboard, setDashboard] = useState<Dashboard | null>(null);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [settlements, setSettlements] = useState<Settlement[]>([]);
  const [runs, setRuns] = useState<PayrollRun[]>([]);
  const [advances, setAdvances] = useState<Advance[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [concepts, setConcepts] = useState<Concept[]>([]);
  const [audit, setAudit] = useState<AuditEntry[]>([]);
  const [salons, setSalons] = useState<Named[]>([]);
  const [employees, setEmployees] = useState<Named[]>([]);
  const [modal, setModal] = useState<'profile' | 'advance' | 'individual' | 'settlement' | 'manual' | 'run' | null>(null);
  const [selectedSettlement, setSelectedSettlement] = useState<Settlement | null>(null);
  const [attendanceFilters, setAttendanceFilters] = useState({ status: '', salonId: '', observed: '', incomplete: '' });
  const [selectedAttendance, setSelectedAttendance] = useState<string[]>([]);
  const [editingProfileId, setEditingProfileId] = useState<string | null>(null);
  const [profileForm, setProfileForm] = useState({ employeeId: '', compensationType: 'hourly', payrollFrequency: 'monthly', hourlyRate: '', dailyRate: '', monthlySalary: '', eventRate: '', effectiveFrom: initialPeriod.from, salonIds: [] as string[], notes: '' });
  const [advanceForm, setAdvanceForm] = useState({ employeeId: '', date: initialPeriod.to, amount: '', reason: '' });
  const [individualForm, setIndividualForm] = useState({ employeeId: '', from: initialPeriod.from, to: initialPeriod.to, notes: '' });
  const [manualForm, setManualForm] = useState({ conceptId: '', amount: '', reason: '' });
  const [runStep, setRunStep] = useState(1);
  const [runForm, setRunForm] = useState({ name: `Liquidación ${initialPeriod.from} a ${initialPeriod.to}`, from: initialPeriod.from, to: initialPeriod.to, frequency: 'monthly', salonIds: [] as string[], employeeIds: [] as string[] });
  const [runValidation, setRunValidation] = useState<{ approved: number; configured: number; selected: number; message: string } | null>(null);
  const [runResult, setRunResult] = useState<{ run?: PayrollRun; created?: string[]; failures?: Array<{ employeeId: string; message: string }> } | null>(null);

  const loadOptions = useCallback(async () => {
    try {
      const [salonsResponse, usersResponse] = await Promise.all([
        api.get<{ salons?: Named[] }>('/salons?active=true'),
        api.get<{ items?: Named[]; users?: Named[] }>('/users/options?role=STAFF&active=true&limit=100')
      ]);
      const nextSalons = salonsResponse.salons ?? [];
      const nextEmployees = usersResponse.items ?? usersResponse.users ?? [];
      setSalons(nextSalons); setEmployees(nextEmployees);
      const preferredEmployee = nextEmployees.find((employee) => employee._id === requestedEmployeeId) ?? nextEmployees[0];
      if (!profileForm.employeeId && preferredEmployee) setProfileForm((current) => ({ ...current, employeeId: preferredEmployee._id }));
      if (!advanceForm.employeeId && nextEmployees[0]) setAdvanceForm((current) => ({ ...current, employeeId: nextEmployees[0]._id }));
      if (!individualForm.employeeId && nextEmployees[0]) setIndividualForm((current) => ({ ...current, employeeId: nextEmployees[0]._id }));
    } catch { setSalons([]); setEmployees([]); }
  }, [advanceForm.employeeId, individualForm.employeeId, profileForm.employeeId, requestedEmployeeId]);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const range = new URLSearchParams({ from: asPayrollDate(period.from), to: asPayrollDate(period.to), limit: '100' });
      if (tab === 'summary') setDashboard(await api.get<Dashboard>(`/payroll/dashboard?${range}`));
      if (tab === 'attendance') {
        if (attendanceFilters.status) range.set('status', attendanceFilters.status); if (attendanceFilters.salonId) range.set('salonId', attendanceFilters.salonId); if (attendanceFilters.observed) range.set('observed', attendanceFilters.observed); if (attendanceFilters.incomplete) range.set('incomplete', attendanceFilters.incomplete);
        const data = await api.get<{ items: Attendance[] }>(`/payroll/attendance?${range}`); setAttendance(data.items ?? []); setSelectedAttendance([]);
      }
      if (tab === 'settlements') { const data = await api.get<{ items: Settlement[] }>(`/payroll/settlements?${range}`); setSettlements(data.items ?? []); }
      if (tab === 'runs') { const data = await api.get<{ items: PayrollRun[] }>('/payroll/runs?limit=100'); setRuns(data.items ?? []); }
      if (tab === 'advances') { const data = await api.get<{ items: Advance[] }>('/payroll/advances?limit=100'); setAdvances(data.items ?? []); }
      if (tab === 'profiles') { const data = await api.get<{ items: Profile[] }>('/payroll/profiles?limit=100'); const items = data.items ?? []; setProfiles(requestedEmployeeId ? items.filter((profile) => profile.employeeId?._id === requestedEmployeeId) : items); }
      if (tab === 'concepts') { const data = await api.get<{ items: Concept[] }>('/payroll/concepts'); setConcepts(data.items ?? []); }
      if (tab === 'history' && canAudit) { const data = await api.get<{ items: AuditEntry[] }>('/payroll/audit'); setAudit(data.items ?? []); }
    } catch (error) { showToast({ message: apiError(error, 'No se pudo cargar la información de liquidaciones.'), variant: 'error' }); }
    finally { setLoading(false); }
  }, [attendanceFilters, canAudit, period, requestedEmployeeId, showToast, tab]);

  useEffect(() => { void loadOptions(); }, [loadOptions]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (tabs.some((item) => item.id === requestedTab)) setTab(requestedTab as Tab); }, [requestedTab]);

  async function runAction(action: () => Promise<unknown>, success: string) {
    setActing(true);
    try { await action(); showToast({ message: success, variant: 'success' }); await load(); }
    catch (error) { showToast({ message: apiError(error, 'No se pudo completar la acción.'), variant: 'error' }); }
    finally { setActing(false); }
  }

  async function download(path: string) {
    try {
      const result = await api.download(path); const url = URL.createObjectURL(result.blob); const link = document.createElement('a'); link.href = url; link.download = result.filename; link.click(); URL.revokeObjectURL(url);
    } catch (error) { showToast({ message: apiError(error, 'No se pudo descargar el archivo.'), variant: 'error' }); }
  }

  function openModal(next: NonNullable<typeof modal>) {
    if (next === 'profile') {
      setEditingProfileId(null);
      setProfileForm({ employeeId: requestedEmployeeId || employees[0]?._id || '', compensationType: 'hourly', payrollFrequency: 'monthly', hourlyRate: '', dailyRate: '', monthlySalary: '', eventRate: '', effectiveFrom: todayPayrollDate(), salonIds: [], notes: '' });
    }
    if (next === 'advance') setAdvanceForm((current) => ({ ...current, employeeId: current.employeeId || employees[0]?._id || '', date: period.to }));
    if (next === 'individual') setIndividualForm((current) => ({ ...current, employeeId: current.employeeId || employees[0]?._id || '', from: period.from, to: period.to }));
    if (next === 'run') { setRunStep(1); setRunResult(null); setRunValidation(null); setRunForm((current) => ({ ...current, from: period.from, to: period.to, name: `Liquidación ${period.from} a ${period.to}` })); }
    setModal(next);
  }

  function editProfile(profile: Profile) {
    setEditingProfileId(profile._id);
    setProfileForm({
      employeeId: profile.employeeId._id,
      compensationType: profile.compensationType,
      payrollFrequency: profile.payrollFrequency,
      hourlyRate: profile.hourlyRateMinor === undefined ? '' : String(profile.hourlyRateMinor / 100),
      dailyRate: profile.dailyRateMinor === undefined ? '' : String(profile.dailyRateMinor / 100),
      monthlySalary: profile.monthlySalaryMinor === undefined ? '' : String(profile.monthlySalaryMinor / 100),
      eventRate: profile.eventRateMinor === undefined ? '' : String(profile.eventRateMinor / 100),
      effectiveFrom: payrollDateInput(profile.effectiveFrom),
      salonIds: (profile.salonIds ?? []).map((salon) => typeof salon === 'string' ? salon : salon._id),
      notes: profile.notes ?? '',
    });
    setModal('profile');
  }

  async function saveProfile() {
    const parsed = z.object({ employeeId: z.string().min(1), effectiveFrom: z.string().min(10), hourlyRate: z.string(), dailyRate: z.string(), monthlySalary: z.string(), eventRate: z.string() }).safeParse(profileForm);
    if (!parsed.success) { showToast({ message: 'Completá el empleado y la vigencia del perfil.', variant: 'error' }); return; }
    const payload = { employeeId: profileForm.employeeId, compensationType: profileForm.compensationType, payrollFrequency: profileForm.payrollFrequency, hourlyRateMinor: profileForm.hourlyRate ? minor(profileForm.hourlyRate) : undefined, dailyRateMinor: profileForm.dailyRate ? minor(profileForm.dailyRate) : undefined, monthlySalaryMinor: profileForm.monthlySalary ? minor(profileForm.monthlySalary) : undefined, eventRateMinor: profileForm.eventRate ? minor(profileForm.eventRate) : undefined, effectiveFrom: asPayrollDate(profileForm.effectiveFrom), salonIds: profileForm.salonIds, notes: profileForm.notes || undefined };
    await runAction(async () => {
      if (editingProfileId) { const { employeeId, ...changes } = payload; await api.patch(`/payroll/profiles/${editingProfileId}`, changes); }
      else await api.post('/payroll/profiles', payload);
      setModal(null); setEditingProfileId(null);
    }, editingProfileId ? 'Configuración de liquidación actualizada correctamente.' : 'Configuración de liquidación creada correctamente.');
  }

  async function deleteProfile(profile: Profile) {
    if (!window.confirm(`¿Eliminar la configuración de ${person(profile.employeeId)}? Si ya fue usada en una liquidación, se desactivará y su historial se conservará.`)) return;
    await runAction(() => api.delete(`/payroll/profiles/${profile._id}`), 'Configuración eliminada del uso futuro. El historial de liquidaciones se conserva.');
  }

  async function saveAdvance() {
    const parsed = z.object({ employeeId: z.string().min(1), amount: z.coerce.number().positive(), reason: z.string().trim().min(3) }).safeParse(advanceForm);
    if (!parsed.success) { showToast({ message: 'Completá empleado, importe y motivo del adelanto.', variant: 'error' }); return; }
    await runAction(async () => { await api.post('/payroll/advances', { employeeId: advanceForm.employeeId, date: asPayrollDate(advanceForm.date), amountMinor: minor(advanceForm.amount), reason: advanceForm.reason }); setModal(null); }, 'Adelanto registrado correctamente.');
  }

  async function createIndividual() {
    if (!individualForm.employeeId) { showToast({ message: 'Seleccioná un empleado.', variant: 'error' }); return; }
    await runAction(async () => { await api.post('/payroll/settlements/individual', { employeeId: individualForm.employeeId, periodStart: asPayrollDate(individualForm.from), periodEnd: asPayrollDate(individualForm.to), notes: individualForm.notes || undefined }); setModal(null); setTab('settlements'); }, 'Borrador de liquidación generado correctamente.');
  }

  async function openSettlement(id: string) {
    setActing(true);
    try { const response = await api.get<{ settlement: Settlement }>(`/payroll/settlements/${id}`); setSelectedSettlement(response.settlement); setModal('settlement'); }
    catch (error) { showToast({ message: apiError(error, 'No se pudo cargar el detalle.'), variant: 'error' }); }
    finally { setActing(false); }
  }

  async function addManualItem() {
    const parsed = z.object({ conceptId: z.string().min(1), amount: z.coerce.number().positive(), reason: z.string().trim().min(3) }).safeParse(manualForm);
    if (!parsed.success || !selectedSettlement) { showToast({ message: 'Seleccioná concepto, importe y motivo.', variant: 'error' }); return; }
    await runAction(async () => { await api.post(`/payroll/settlements/${selectedSettlement._id}/items`, { conceptId: manualForm.conceptId, amountMinor: minor(manualForm.amount), reason: manualForm.reason }); const response = await api.get<{ settlement: Settlement }>(`/payroll/settlements/${selectedSettlement._id}`); setSelectedSettlement(response.settlement); setModal('settlement'); }, 'Concepto manual agregado y cálculo actualizado.');
  }

  async function cancelSettlement(settlement: Settlement) {
    const reason = window.prompt(`Motivo para eliminar la liquidación de ${person(settlement.employeeId)}`);
    if (!reason) return;
    if (reason.trim().length < 3) { showToast({ message: 'Indicá un motivo de al menos 3 caracteres.', variant: 'error' }); return; }
    await runAction(async () => {
      await api.post(`/payroll/settlements/${settlement._id}/cancel`, { reason: reason.trim() });
      if (selectedSettlement?._id === settlement._id) { setSelectedSettlement(null); setModal(null); }
    }, 'Liquidación cancelada. Las asistencias y adelantos reservados quedaron liberados.');
  }

  async function validateRun() {
    setActing(true);
    try {
      const selected = runForm.employeeIds.length ? runForm.employeeIds : employees.map((employee) => employee._id);
      const query = new URLSearchParams({ from: asPayrollDate(runForm.from), to: asPayrollDate(runForm.to), limit: '100' });
      const [attendanceResponse, profileResponse] = await Promise.all([api.get<{ items: Attendance[] }>(`/payroll/attendance?${query}`), api.get<{ items: Profile[] }>('/payroll/profiles?limit=100')]);
      const approved = (attendanceResponse.items ?? []).filter((item) => item.payrollStatus === 'approved' && selected.includes(item.userId._id)).length;
      setRunValidation({ selected: selected.length, approved, configured: selected.filter((id) => (profileResponse.items ?? []).some((profile) => profile.employeeId._id === id && profile.isActive)).length, message: approved ? 'La validación encontró asistencias aprobadas para calcular.' : 'No hay asistencias aprobadas para los empleados seleccionados.' });
      setRunStep(2);
    } catch (error) { showToast({ message: apiError(error, 'No se pudo validar el lote.'), variant: 'error' }); }
    finally { setActing(false); }
  }

  async function generateRun() {
    setActing(true);
    try {
      const created = await api.post<{ run: PayrollRun }>('/payroll/runs', { name: runForm.name, periodStart: asPayrollDate(runForm.from), periodEnd: asPayrollDate(runForm.to), frequency: runForm.frequency, salonIds: runForm.salonIds, employeeIds: runForm.employeeIds, idempotencyKey: `web-${Date.now()}-${Math.random().toString(36).slice(2)}` });
      const calculated = await api.post<{ run: PayrollRun; created: string[]; failures: Array<{ employeeId: string; message: string }> }>(`/payroll/runs/${created.run._id}/calculate`, {});
      setRunResult(calculated); setRunStep(5); await load();
    } catch (error) { showToast({ message: apiError(error, 'No se pudo generar el lote.'), variant: 'error' }); }
    finally { setActing(false); }
  }

  const metricCards: Array<[string, number, typeof UsersRound]> = dashboard ? [
    ['Sin perfil salarial', dashboard.withoutProfile, UsersRound], ['Marcaciones incompletas', dashboard.incomplete, X], ['Pendientes de aprobación', dashboard.pendingAttendance, ClipboardCheck], ['En revisión', dashboard.review, ListChecks], ['Pendientes de pago', dashboard.unpaid, CircleDollarSign]
  ] : [];
  const attendanceNeedingReview = useMemo(() => attendance.filter((item) => item.payrollStatus === 'pending' || item.flags.includes('observed') || item.flags.includes('incomplete') || ['incomplete', 'under_review'].includes(item.status)), [attendance]);

  return <section className="space-y-6">
    <PageHeader title="Liquidación de Sueldos" description="Herramienta administrativa interna para validar jornadas, calcular haberes y registrar pagos. Los importes se muestran en pesos y se calculan de forma segura en el servidor." action={<div className="flex flex-wrap gap-2">{canCreate ? <Button onClick={() => openModal('individual')}><Plus className="mr-2 h-4 w-4" />Liquidación individual</Button> : null}{canCreate ? <Button variant="secondary" onClick={() => openModal('run')}><ListChecks className="mr-2 h-4 w-4" />Nuevo lote</Button> : null}</div>} />
    <div className="flex flex-wrap gap-2 rounded-2xl border border-zinc-200 bg-white p-3 shadow-sm">{tabs.map(({ id, label, icon: Icon }) => <button key={id} type="button" onClick={() => setTab(id)} className={`inline-flex items-center gap-2 rounded-xl px-3 py-2 text-sm font-medium transition ${tab === id ? 'bg-zinc-950 text-white' : 'text-zinc-600 hover:bg-zinc-100'}`}><Icon className="h-4 w-4" />{label}</button>)}</div>
    <div className="flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4 shadow-sm"><Field label="Desde"><Input type="date" value={period.from} onChange={(event) => setPeriod((current) => ({ ...current, from: event.target.value }))} /></Field><Field label="Hasta"><Input type="date" value={period.to} onChange={(event) => setPeriod((current) => ({ ...current, to: event.target.value }))} /></Field><Button variant="secondary" disabled={loading} onClick={() => void load()}><RefreshCw className="mr-2 h-4 w-4" />Actualizar</Button>{canExport && tab === 'settlements' ? <><Button variant="secondary" onClick={() => void download(`/payroll/settlements/export/csv?from=${encodeURIComponent(asPayrollDate(period.from))}&to=${encodeURIComponent(asPayrollDate(period.to))}`)}><Download className="mr-2 h-4 w-4" />CSV</Button><Button variant="secondary" onClick={() => void download(`/payroll/settlements/export/excel?from=${encodeURIComponent(asPayrollDate(period.from))}&to=${encodeURIComponent(asPayrollDate(period.to))}`)}><Download className="mr-2 h-4 w-4" />Excel</Button></> : null}</div>

    {tab === 'summary' ? <div className="space-y-5">{loading ? <p className="text-sm text-zinc-500">Cargando resumen…</p> : <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{metricCards.map(([label, value, Icon]) => <article key={String(label)} className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm"><Icon className="h-5 w-5 text-zinc-500" /><p className="mt-5 text-3xl font-semibold text-zinc-950">{value}</p><p className="mt-1 text-sm text-zinc-500">{label}</p></article>)}</div><article className="rounded-2xl border border-zinc-200 bg-zinc-950 p-6 text-white"><p className="text-sm text-zinc-300">Total estimado del período</p><p className="mt-2 text-3xl font-semibold">{money(dashboard?.estimatedAmountMinor)}</p><p className="mt-2 text-xs text-zinc-400">Incluye liquidaciones borrador, en revisión y aprobadas del período seleccionado.</p></article><section className="rounded-2xl border border-zinc-200 bg-white shadow-sm"><header className="border-b border-zinc-100 px-5 py-4"><h2 className="font-semibold">Últimas liquidaciones</h2></header><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500"><tr><th className="px-5 py-3">Empleado</th><th className="px-5 py-3">Período</th><th className="px-5 py-3">Neto</th><th className="px-5 py-3">Estado</th></tr></thead><tbody>{(dashboard?.recent ?? []).map((settlement) => <tr key={settlement._id} className="border-t border-zinc-100"><td className="px-5 py-3 font-medium">{person(settlement.employeeId)}</td><td className="px-5 py-3">{date(settlement.periodStart)} — {date(settlement.periodEnd)}</td><td className="px-5 py-3">{money(settlement.netAmountMinor, settlement.currency)}</td><td className="px-5 py-3"><Badge value={settlement.status} /></td></tr>)}</tbody></table></div></section></>}</div> : null}

    {tab === 'attendance' ? <div className="space-y-4"><div className="flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4 shadow-sm"><Field label="Estado"><Select value={attendanceFilters.status} onChange={(event) => setAttendanceFilters((current) => ({ ...current, status: event.target.value }))}><option value="">Todos</option><option value="pending">Pendiente</option><option value="approved">Aprobada</option><option value="rejected">Rechazada</option></Select></Field><Field label="Salón"><Select value={attendanceFilters.salonId} onChange={(event) => setAttendanceFilters((current) => ({ ...current, salonId: event.target.value }))}><option value="">Todos</option>{salons.map((salon) => <option key={salon._id} value={salon._id}>{salon.name}</option>)}</Select></Field><label className="flex items-center gap-2 pb-2.5 text-sm"><input type="checkbox" checked={attendanceFilters.observed === 'true'} onChange={(event) => setAttendanceFilters((current) => ({ ...current, observed: event.target.checked ? 'true' : '' }))} />Sólo observadas</label><label className="flex items-center gap-2 pb-2.5 text-sm"><input type="checkbox" checked={attendanceFilters.incomplete === 'true'} onChange={(event) => setAttendanceFilters((current) => ({ ...current, incomplete: event.target.checked ? 'true' : '' }))} />Sólo incompletas</label>{canAttendance && selectedAttendance.length ? <Button onClick={() => void runAction(() => api.post('/payroll/attendance/bulk-approve', { sessionIds: selectedAttendance }), `${selectedAttendance.length} jornadas procesadas.`)}>Aprobar seleccionadas</Button> : null}</div><div className="overflow-x-auto rounded-2xl border border-zinc-200 bg-white shadow-sm"><table className="w-full min-w-[1050px] text-left text-sm"><thead className="bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500"><tr><th className="px-4 py-3"><input aria-label="Seleccionar todas las asistencias" type="checkbox" checked={attendance.length > 0 && selectedAttendance.length === attendance.filter((item) => item.payrollStatus === 'pending').length} onChange={(event) => setSelectedAttendance(event.target.checked ? attendance.filter((item) => item.payrollStatus === 'pending').map((item) => item._id) : [])} /></th><th className="px-4 py-3">Empleado</th><th className="px-4 py-3">Salón / evento</th><th className="px-4 py-3">Entrada / salida</th><th className="px-4 py-3">Horas</th><th className="px-4 py-3">Aprobadas</th><th className="px-4 py-3">Estado</th><th className="px-4 py-3">Observaciones</th><th className="px-4 py-3" /></tr></thead><tbody>{attendance.map((item) => <tr key={item._id} className="border-t border-zinc-100 align-top"><td className="px-4 py-3"><input aria-label={`Seleccionar jornada de ${person(item.userId)}`} disabled={item.payrollStatus !== 'pending'} type="checkbox" checked={selectedAttendance.includes(item._id)} onChange={(event) => setSelectedAttendance((current) => event.target.checked ? [...current, item._id] : current.filter((id) => id !== item._id))} /></td><td className="px-4 py-3 font-medium">{person(item.userId)}</td><td className="px-4 py-3"><p>{item.salonId?.name ?? 'Tarea general'}</p><p className="text-xs text-zinc-500">{item.eventId?.name ?? item.eventId?.fullName ?? 'Sin evento'}</p></td><td className="px-4 py-3">{dateTime(item.startedAt)}<br />{dateTime(item.endedAt)}</td><td className="px-4 py-3">{minutes(item.workedMinutes)}</td><td className="px-4 py-3">{minutes(item.approvedMinutes)}</td><td className="px-4 py-3"><Badge value={item.payrollStatus} /></td><td className="px-4 py-3"><div className="flex flex-wrap gap-1">{item.flags.map((flag) => <span key={flag} className="rounded bg-amber-50 px-2 py-1 text-xs text-amber-800">{flagsLabels[flag] ?? flag}</span>) || '—'}</div></td><td className="px-4 py-3"><div className="flex">{canAttendance && item.payrollStatus === 'pending' ? <><TableActionButton icon={Check} label="Aprobar asistencia" onClick={() => void runAction(() => api.post(`/payroll/attendance/${item._id}/approve`, {}), 'Asistencia aprobada para liquidación.')} /><TableActionButton icon={X} label="Rechazar asistencia" onClick={() => { const reason = window.prompt('Motivo del rechazo'); if (reason) void runAction(() => api.post(`/payroll/attendance/${item._id}/reject`, { reason }), 'Asistencia rechazada.'); }} /></> : null}</div></td></tr>)}</tbody></table>{!loading && !attendance.length ? <p className="p-8 text-center text-sm text-zinc-500">No hay asistencias para los filtros seleccionados.</p> : null}</div></div> : null}

    {tab === 'settlements' ? <SettlementTable settlements={settlements} loading={loading} canCalculate={canCalculate} canApprove={canApprove} canPay={canPay} canExport={canExport} acting={acting} onOpen={openSettlement} onAction={runAction} onCancel={cancelSettlement} /> : null}

    {tab === 'attendance' && attendanceNeedingReview.length ? <aside className="rounded-2xl border border-amber-200 bg-amber-50 p-4"><h2 className="font-semibold text-amber-950">Revisión operativa rápida</h2><p className="mt-1 text-sm text-amber-900">Abrí la jornada que esté pendiente u observada para corregir su estado desde Asistencia.</p><div className="mt-3 flex flex-wrap gap-2">{attendanceNeedingReview.map((item) => <Button key={item._id} variant="secondary" onClick={() => router.push(`/admin/attendance?tab=history&sessionId=${encodeURIComponent(item._id)}`)}>{person(item.userId)} · {date(item.startedAt)}</Button>)}</div></aside> : null}

    {tab === 'runs' ? <div className="space-y-4"><div className="flex justify-end">{canCreate ? <Button onClick={() => openModal('run')}><Plus className="mr-2 h-4 w-4" />Nuevo lote</Button> : null}</div><div className="overflow-x-auto rounded-2xl border border-zinc-200 bg-white shadow-sm"><table className="w-full min-w-[780px] text-left text-sm"><thead className="bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500"><tr><th className="px-5 py-3">Lote</th><th className="px-5 py-3">Período</th><th className="px-5 py-3">Liquidaciones</th><th className="px-5 py-3">Neto</th><th className="px-5 py-3">Estado</th><th className="px-5 py-3" /></tr></thead><tbody>{runs.map((run) => <tr key={run._id} className="border-t border-zinc-100"><td className="px-5 py-3 font-medium">{run.name}</td><td className="px-5 py-3">{date(run.periodStart)} — {date(run.periodEnd)}</td><td className="px-5 py-3">{run.totals?.settlements ?? 0}</td><td className="px-5 py-3">{money(run.totals?.netAmountMinor)}</td><td className="px-5 py-3"><Badge value={run.status} /></td><td className="px-5 py-3"><div className="flex">{canCalculate && ['draft', 'calculated'].includes(run.status) ? <TableActionButton icon={RefreshCw} label="Calcular lote" onClick={() => void runAction(() => api.post(`/payroll/runs/${run._id}/calculate`, {}), 'Lote calculado.')} /> : null}{canCalculate && ['calculated', 'under_review'].includes(run.status) ? <TableActionButton icon={Send} label="Enviar lote a revisión" onClick={() => void runAction(() => api.post(`/payroll/runs/${run._id}/submit-review`, {}), 'Lote enviado a revisión.')} /> : null}{canApprove && ['calculated', 'under_review'].includes(run.status) ? <TableActionButton icon={Check} label="Aprobar lote" onClick={() => void runAction(() => api.post(`/payroll/runs/${run._id}/approve`, {}), 'Lote aprobado.')} /> : null}{canPay && ['approved', 'partially_paid'].includes(run.status) ? <TableActionButton icon={CircleDollarSign} label="Marcar lote como pagado" onClick={() => void runAction(() => api.post(`/payroll/runs/${run._id}/mark-paid`, {}), 'Pagos del lote registrados.')} /> : null}{canExport ? <TableActionButton icon={Download} label="Descargar PDF consolidado" onClick={() => void download(`/payroll/runs/${run._id}/export/pdf`)} /> : null}</div></td></tr>)}</tbody></table>{!loading && !runs.length ? <p className="p-8 text-center text-sm text-zinc-500">Todavía no hay lotes de liquidación.</p> : null}</div></div> : null}

    {tab === 'advances' ? <div className="space-y-4"><div className="flex justify-end">{canCreate ? <Button onClick={() => openModal('advance')}><Plus className="mr-2 h-4 w-4" />Registrar adelanto</Button> : null}</div><DataTable columns={['Empleado', 'Fecha', 'Importe', 'Motivo', 'Estado']} empty="No hay adelantos registrados." rows={advances.map((advance) => [person(advance.employeeId), date(advance.date), money(advance.amountMinor, advance.currency), advance.reason, <Badge key={advance._id} value={advance.status} />])} /></div> : null}

    {tab === 'profiles' ? <div className="space-y-4"><div className="flex justify-end">{canProfiles ? <Button onClick={() => openModal('profile')}><Plus className="mr-2 h-4 w-4" />Nueva configuración</Button> : null}</div><DataTable columns={['Empleado', 'Tipo', 'Frecuencia', 'Tarifas', 'Vigencia', 'Versión', 'Estado', 'Acciones']} empty="No hay configuraciones salariales cargadas." rows={profiles.map((profile) => [person(profile.employeeId), compensationLabels[profile.compensationType] ?? profile.compensationType, profile.payrollFrequency, [profile.hourlyRateMinor ? `Hora ${money(profile.hourlyRateMinor, profile.currency)}` : '', profile.dailyRateMinor ? `Jornada ${money(profile.dailyRateMinor, profile.currency)}` : '', profile.monthlySalaryMinor ? `Mensual ${money(profile.monthlySalaryMinor, profile.currency)}` : '', profile.eventRateMinor ? `Evento ${money(profile.eventRateMinor, profile.currency)}` : ''].filter(Boolean).join(' · ') || 'Sin tarifa', `${date(profile.effectiveFrom)}${profile.effectiveTo ? ` — ${date(profile.effectiveTo)}` : ' — vigente'}`, `v${profile.version}`, <span key={`${profile._id}-state`} className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${profile.isActive ? 'bg-emerald-100 text-emerald-700' : 'bg-zinc-100 text-zinc-600'}`}>{profile.isActive ? 'Vigente' : 'Histórica'}</span>, canProfiles && profile.isActive ? <div key={`${profile._id}-actions`} className="flex"><TableActionButton icon={Pencil} label="Editar configuración" disabled={acting} onClick={() => editProfile(profile)} /><TableActionButton icon={Trash2} label="Eliminar configuración" disabled={acting} onClick={() => void deleteProfile(profile)} /></div> : '—'])} /></div> : null}

    {tab === 'concepts' ? <ConceptsView concepts={concepts} loading={loading} canProfiles={canProfiles} onReload={load} showToast={showToast} /> : null}

    {tab === 'history' ? <div className="rounded-2xl border border-zinc-200 bg-white shadow-sm">{canAudit ? <><header className="border-b border-zinc-100 px-5 py-4"><h2 className="font-semibold">Auditoría de liquidaciones</h2><p className="mt-1 text-sm text-zinc-500">Incluye perfiles, correcciones, cálculos, aprobaciones, pagos y exportaciones.</p></header><div className="divide-y divide-zinc-100">{audit.map((entry) => <article key={entry._id} className="px-5 py-4"><p className="font-medium text-zinc-900">{entry.action}</p><p className="mt-1 text-sm text-zinc-500">{person(entry.actorUserId)} · {dateTime(entry.createdAt)} · {entry.entityType}</p>{entry.metadata?.reason ? <p className="mt-2 text-sm text-zinc-700">Motivo: {entry.metadata.reason}</p> : null}</article>)}{!loading && !audit.length ? <p className="p-8 text-center text-sm text-zinc-500">No hay acciones auditadas para mostrar.</p> : null}</div></> : <p className="p-8 text-sm text-zinc-500">Tu perfil no tiene permiso para consultar la auditoría salarial.</p>}</div> : null}

    <Modal open={modal === 'profile'} onClose={() => { setModal(null); setEditingProfileId(null); }} title={editingProfileId ? 'Editar configuración de liquidación' : 'Nueva configuración de liquidación'} description={editingProfileId ? 'Corregí los datos. Si el perfil ya fue usado, se conserva la liquidación histórica y se crea una nueva versión desde la fecha elegida.' : 'Definí las condiciones de pago para este empleado.'}><div className="grid gap-4 p-6 sm:grid-cols-2"><Field label="Empleado"><Select disabled={Boolean(editingProfileId)} value={profileForm.employeeId} onChange={(event) => setProfileForm((current) => ({ ...current, employeeId: event.target.value }))}>{employees.map((employee) => <option key={employee._id} value={employee._id}>{person(employee)}</option>)}</Select></Field><Field label="Tipo de pago"><Select value={profileForm.compensationType} onChange={(event) => setProfileForm((current) => ({ ...current, compensationType: event.target.value }))}><option value="hourly">Por hora</option><option value="daily">Por jornada</option><option value="monthly">Mensual</option><option value="per_event">Por evento</option><option value="mixed">Mixto</option></Select></Field><Field label="Frecuencia"><Select value={profileForm.payrollFrequency} onChange={(event) => setProfileForm((current) => ({ ...current, payrollFrequency: event.target.value }))}><option value="weekly">Semanal</option><option value="biweekly">Quincenal</option><option value="monthly">Mensual</option><option value="custom">Personalizada</option></Select></Field><Field label="Vigente desde"><Input type="date" value={profileForm.effectiveFrom} onChange={(event) => setProfileForm((current) => ({ ...current, effectiveFrom: event.target.value }))} /></Field><Field label="Valor hora (pesos)"><Input inputMode="decimal" value={profileForm.hourlyRate} onChange={(event) => setProfileForm((current) => ({ ...current, hourlyRate: event.target.value }))} /></Field><Field label="Valor jornada (pesos)"><Input inputMode="decimal" value={profileForm.dailyRate} onChange={(event) => setProfileForm((current) => ({ ...current, dailyRate: event.target.value }))} /></Field><Field label="Salario mensual (pesos)"><Input inputMode="decimal" value={profileForm.monthlySalary} onChange={(event) => setProfileForm((current) => ({ ...current, monthlySalary: event.target.value }))} /></Field><Field label="Valor por evento (pesos)"><Input inputMode="decimal" value={profileForm.eventRate} onChange={(event) => setProfileForm((current) => ({ ...current, eventRate: event.target.value }))} /></Field><Field label="Salones relacionados"><Select multiple value={profileForm.salonIds} onChange={(event) => setProfileForm((current) => ({ ...current, salonIds: Array.from(event.target.selectedOptions).map((option) => option.value) }))}>{salons.map((salon) => <option key={salon._id} value={salon._id}>{salon.name}</option>)}</Select></Field><div className="sm:col-span-2"><Field label="Notas"><Textarea value={profileForm.notes} onChange={(event) => setProfileForm((current) => ({ ...current, notes: event.target.value }))} /></Field></div><footer className="sm:col-span-2 flex justify-end gap-3"><Button variant="secondary" onClick={() => { setModal(null); setEditingProfileId(null); }}>Cancelar</Button><Button disabled={acting} onClick={() => void saveProfile()}>{acting ? 'Guardando…' : editingProfileId ? 'Guardar cambios' : 'Crear configuración'}</Button></footer></div></Modal>

    <Modal open={modal === 'advance'} onClose={() => setModal(null)} title="Registrar adelanto" description="El adelanto se descontará una sola vez en la próxima liquidación aplicable."><div className="space-y-4 p-6"><Field label="Empleado"><Select value={advanceForm.employeeId} onChange={(event) => setAdvanceForm((current) => ({ ...current, employeeId: event.target.value }))}>{employees.map((employee) => <option key={employee._id} value={employee._id}>{person(employee)}</option>)}</Select></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Fecha"><Input type="date" value={advanceForm.date} onChange={(event) => setAdvanceForm((current) => ({ ...current, date: event.target.value }))} /></Field><Field label="Importe (pesos)"><Input inputMode="decimal" value={advanceForm.amount} onChange={(event) => setAdvanceForm((current) => ({ ...current, amount: event.target.value }))} /></Field></div><Field label="Motivo"><Textarea value={advanceForm.reason} onChange={(event) => setAdvanceForm((current) => ({ ...current, reason: event.target.value }))} /></Field><footer className="flex justify-end gap-3"><Button variant="secondary" onClick={() => setModal(null)}>Cancelar</Button><Button disabled={acting} onClick={() => void saveAdvance()}>{acting ? 'Guardando…' : 'Registrar adelanto'}</Button></footer></div></Modal>

    <Modal open={modal === 'individual'} onClose={() => setModal(null)} title="Generar liquidación individual" description="Sólo se incluirán asistencias aprobadas que todavía no estén reservadas."><div className="space-y-4 p-6"><Field label="Empleado"><Select value={individualForm.employeeId} onChange={(event) => setIndividualForm((current) => ({ ...current, employeeId: event.target.value }))}>{employees.map((employee) => <option key={employee._id} value={employee._id}>{person(employee)}</option>)}</Select></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Desde"><Input type="date" value={individualForm.from} onChange={(event) => setIndividualForm((current) => ({ ...current, from: event.target.value }))} /></Field><Field label="Hasta"><Input type="date" value={individualForm.to} onChange={(event) => setIndividualForm((current) => ({ ...current, to: event.target.value }))} /></Field></div><Field label="Observaciones"><Textarea value={individualForm.notes} onChange={(event) => setIndividualForm((current) => ({ ...current, notes: event.target.value }))} /></Field><footer className="flex justify-end gap-3"><Button variant="secondary" onClick={() => setModal(null)}>Cancelar</Button><Button disabled={acting} onClick={() => void createIndividual()}>{acting ? 'Generando…' : 'Generar borrador'}</Button></footer></div></Modal>

    <Modal open={modal === 'settlement'} onClose={() => setModal(null)} title="Detalle de liquidación" description={selectedSettlement ? `${person(selectedSettlement.employeeId)} · ${date(selectedSettlement.periodStart)} al ${date(selectedSettlement.periodEnd)}` : ''} wide><div className="space-y-5 p-6">{selectedSettlement ? <><div className="flex flex-wrap items-center justify-between gap-3"><div><Badge value={selectedSettlement.status} /> <span className="ml-2"><Badge value={selectedSettlement.paymentStatus} /></span></div><div className="flex gap-2">{canCalculate && selectedSettlement.status === 'draft' ? <Button variant="secondary" onClick={() => void runAction(async () => { await api.post(`/payroll/settlements/${selectedSettlement._id}/recalculate`, {}); await openSettlement(selectedSettlement._id); }, 'Liquidación recalculada.')}>Recalcular</Button> : null}{canCalculate && ['draft', 'under_review'].includes(selectedSettlement.status) ? <Button variant="secondary" onClick={() => { setManualForm({ conceptId: concepts[0]?._id ?? '', amount: '', reason: '' }); setModal('manual'); }}>Agregar concepto</Button> : null}{canCalculate && ['draft', 'under_review'].includes(selectedSettlement.status) ? <Button variant="danger" onClick={() => void cancelSettlement(selectedSettlement)}>Eliminar liquidación</Button> : null}{canApprove && ['draft', 'under_review'].includes(selectedSettlement.status) ? <Button onClick={() => void runAction(async () => { await api.post(`/payroll/settlements/${selectedSettlement._id}/approve`, {}); await openSettlement(selectedSettlement._id); }, 'Liquidación aprobada.')}>Aprobar</Button> : null}{canPay && selectedSettlement.status === 'approved' && selectedSettlement.paymentStatus !== 'paid' ? <Button onClick={() => void runAction(async () => { await api.post(`/payroll/settlements/${selectedSettlement._id}/mark-paid`, {}); await openSettlement(selectedSettlement._id); }, 'Pago registrado.')}>Marcar pagada</Button> : null}{canExport && selectedSettlement.status === 'approved' ? <Button variant="secondary" onClick={() => void runAction(async () => { const response = await api.post<{ receipt: { secureUrl?: string } }>(`/payroll/settlements/${selectedSettlement._id}/receipt`, {}); if (response.receipt.secureUrl) window.open(response.receipt.secureUrl, '_blank', 'noopener,noreferrer'); }, 'Comprobante generado.')}>Comprobante</Button> : null}</div></div><div className="grid gap-4 sm:grid-cols-5"><Metric label="Base" value={money(selectedSettlement.baseAmountMinor, selectedSettlement.currency)} /><Metric label="Haberes" value={money(selectedSettlement.earningsAmountMinor, selectedSettlement.currency)} /><Metric label="Descuentos" value={money(selectedSettlement.deductionsAmountMinor, selectedSettlement.currency)} /><Metric label="Bruto" value={money(selectedSettlement.grossAmountMinor, selectedSettlement.currency)} /><Metric label="Neto" value={money(selectedSettlement.netAmountMinor, selectedSettlement.currency)} /></div><div className="overflow-x-auto rounded-xl border border-zinc-200"><table className="w-full min-w-[650px] text-left text-sm"><thead className="bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500"><tr><th className="px-4 py-3">Concepto</th><th className="px-4 py-3">Cantidad</th><th className="px-4 py-3">Unitario</th><th className="px-4 py-3">Importe</th></tr></thead><tbody>{(selectedSettlement.items ?? []).map((item, index) => <tr key={`${item.conceptName}-${index}`} className="border-t border-zinc-100"><td className="px-4 py-3">{item.conceptType === 'deduction' ? 'Descuento · ' : ''}{item.conceptName}{item.reason ? <span className="block text-xs text-zinc-500">{item.reason}</span> : null}</td><td className="px-4 py-3">{item.quantity} {item.unit}</td><td className="px-4 py-3">{money(item.unitAmountMinor, selectedSettlement.currency)}</td><td className="px-4 py-3 font-medium">{item.conceptType === 'deduction' ? '-' : ''}{money(item.subtotalMinor, selectedSettlement.currency)}</td></tr>)}</tbody></table></div>{selectedSettlement.calculationDetails?.warnings?.length ? <p className="rounded-xl bg-amber-50 p-3 text-sm text-amber-800">{selectedSettlement.calculationDetails.warnings.join(' ')}</p> : null}</> : null}</div></Modal>

    <Modal open={modal === 'manual'} onClose={() => { setModal('settlement'); }} title="Agregar concepto manual" description="Los conceptos manuales requieren un motivo y sólo se aplican antes de aprobar."><div className="space-y-4 p-6"><Field label="Concepto"><Select value={manualForm.conceptId} onChange={(event) => setManualForm((current) => ({ ...current, conceptId: event.target.value }))}>{concepts.filter((concept) => concept.isActive && !concept.isAutomatic).map((concept) => <option key={concept._id} value={concept._id}>{concept.name} · {concept.type === 'earning' ? 'Haber' : 'Descuento'}</option>)}</Select></Field><Field label="Importe (pesos)"><Input inputMode="decimal" value={manualForm.amount} onChange={(event) => setManualForm((current) => ({ ...current, amount: event.target.value }))} /></Field><Field label="Motivo"><Textarea value={manualForm.reason} onChange={(event) => setManualForm((current) => ({ ...current, reason: event.target.value }))} /></Field><footer className="flex justify-end gap-3"><Button variant="secondary" onClick={() => setModal('settlement')}>Cancelar</Button><Button disabled={acting} onClick={() => void addManualItem()}>{acting ? 'Agregando…' : 'Agregar concepto'}</Button></footer></div></Modal>

    <Modal open={modal === 'run'} onClose={() => setModal(null)} title="Asistente de lote de liquidación" description={`Paso ${runStep} de 5`} wide><div className="space-y-5 p-6"><div className="flex gap-2">{[1, 2, 3, 4, 5].map((step) => <span key={step} className={`grid h-7 w-7 place-items-center rounded-full text-xs font-semibold ${step <= runStep ? 'bg-zinc-950 text-white' : 'bg-zinc-100 text-zinc-500'}`}>{step}</span>)}</div>{runStep === 1 ? <div className="grid gap-4 sm:grid-cols-2"><Field label="Nombre"><Input value={runForm.name} onChange={(event) => setRunForm((current) => ({ ...current, name: event.target.value }))} /></Field><Field label="Frecuencia"><Select value={runForm.frequency} onChange={(event) => setRunForm((current) => ({ ...current, frequency: event.target.value }))}><option value="weekly">Semanal</option><option value="biweekly">Quincenal</option><option value="monthly">Mensual</option><option value="custom">Personalizada</option></Select></Field><Field label="Desde"><Input type="date" value={runForm.from} onChange={(event) => setRunForm((current) => ({ ...current, from: event.target.value }))} /></Field><Field label="Hasta"><Input type="date" value={runForm.to} onChange={(event) => setRunForm((current) => ({ ...current, to: event.target.value }))} /></Field><Field label="Salones"><Select multiple value={runForm.salonIds} onChange={(event) => setRunForm((current) => ({ ...current, salonIds: Array.from(event.target.selectedOptions).map((option) => option.value) }))}>{salons.map((salon) => <option key={salon._id} value={salon._id}>{salon.name}</option>)}</Select></Field><Field label="Empleados (vacío = todos los habilitados del alcance)"><Select multiple value={runForm.employeeIds} onChange={(event) => setRunForm((current) => ({ ...current, employeeIds: Array.from(event.target.selectedOptions).map((option) => option.value) }))}>{employees.map((employee) => <option key={employee._id} value={employee._id}>{person(employee)}</option>)}</Select></Field></div> : null}{runStep === 2 ? <div className="rounded-xl border border-zinc-200 p-5"><h3 className="font-semibold">Validación previa</h3><p className="mt-2 text-sm text-zinc-600">{runValidation?.message}</p><dl className="mt-4 grid gap-3 sm:grid-cols-3"><Metric label="Empleados seleccionados" value={String(runValidation?.selected ?? 0)} /><Metric label="Con perfil vigente" value={String(runValidation?.configured ?? 0)} /><Metric label="Asistencias aprobadas" value={String(runValidation?.approved ?? 0)} /></dl></div> : null}{runStep === 3 ? <div className="rounded-xl border border-zinc-200 p-5"><h3 className="font-semibold">Previsualización</h3><p className="mt-2 text-sm text-zinc-600">Al continuar se generarán exclusivamente borradores para empleados con perfil vigente y asistencias aprobadas. Las fallas se informarán una por una y no se ocultarán.</p><p className="mt-3 text-sm text-zinc-600">El cálculo se ejecuta en el backend; el importe que ves después es el resultado explicable guardado en cada liquidación.</p></div> : null}{runStep === 4 ? <div className="rounded-xl border border-zinc-200 p-5"><h3 className="font-semibold">Generar borradores</h3><p className="mt-2 text-sm text-zinc-600">Esta acción crea el lote y calcula sus liquidaciones. Las asistencias quedan reservadas para evitar doble liquidación.</p></div> : null}{runStep === 5 ? <div className="rounded-xl border border-zinc-200 p-5"><h3 className="font-semibold">Resultado de generación</h3><p className="mt-2 text-sm text-zinc-600">Se generaron {runResult?.created?.length ?? 0} borradores.</p>{runResult?.failures?.length ? <ul className="mt-3 list-disc space-y-1 pl-5 text-sm text-red-700">{runResult.failures.map((failure) => <li key={failure.employeeId}>{failure.message}</li>)}</ul> : <p className="mt-3 text-sm text-emerald-700">No hubo errores. Revisá el lote antes de aprobarlo.</p>}</div> : null}<footer className="flex justify-between gap-3"><Button variant="secondary" onClick={() => runStep === 1 ? setModal(null) : setRunStep((step) => step - 1)}>{runStep === 1 ? 'Cancelar' : 'Anterior'}</Button>{runStep === 1 ? <Button disabled={!runForm.name || !runForm.salonIds.length} onClick={() => void validateRun()}>{acting ? 'Validando…' : 'Validar alcance'}</Button> : runStep === 2 ? <Button onClick={() => setRunStep(3)}>Ver previsualización</Button> : runStep === 3 ? <Button onClick={() => setRunStep(4)}>Preparar borradores</Button> : runStep === 4 ? <Button disabled={acting} onClick={() => void generateRun()}>{acting ? 'Generando…' : 'Generar y calcular'}</Button> : <Button onClick={() => { setModal(null); setTab('runs'); }}>Ver lote</Button>}</footer></div></Modal>
  </section>;
}

function SettlementTable({ settlements, loading, canCalculate, canApprove, canPay, canExport, acting, onOpen, onAction, onCancel }: { settlements: Settlement[]; loading: boolean; canCalculate: boolean; canApprove: boolean; canPay: boolean; canExport: boolean; acting: boolean; onOpen: (id: string) => Promise<void>; onAction: (action: () => Promise<unknown>, success: string) => Promise<void>; onCancel: (settlement: Settlement) => Promise<void> }) {
  return <div className="overflow-x-auto rounded-2xl border border-zinc-200 bg-white shadow-sm"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500"><tr><th className="px-5 py-3">Empleado</th><th className="px-5 py-3">Período</th><th className="px-5 py-3">Haberes</th><th className="px-5 py-3">Descuentos</th><th className="px-5 py-3">Neto</th><th className="px-5 py-3">Estado</th><th className="px-5 py-3">Pago</th><th className="px-5 py-3" /></tr></thead><tbody>{settlements.map((settlement) => <tr key={settlement._id} className="border-t border-zinc-100"><td className="px-5 py-3 font-medium">{person(settlement.employeeId)}</td><td className="px-5 py-3">{date(settlement.periodStart)} — {date(settlement.periodEnd)}</td><td className="px-5 py-3">{money(settlement.grossAmountMinor, settlement.currency)}</td><td className="px-5 py-3">{money(settlement.deductionsAmountMinor, settlement.currency)}</td><td className="px-5 py-3 font-semibold">{money(settlement.netAmountMinor, settlement.currency)}</td><td className="px-5 py-3"><Badge value={settlement.status} /></td><td className="px-5 py-3"><Badge value={settlement.paymentStatus} /></td><td className="px-5 py-3"><div className="flex"> <TableActionButton icon={Eye} label="Ver detalle de liquidación" disabled={acting} onClick={() => void onOpen(settlement._id)} />{canCalculate && settlement.status === 'draft' ? <TableActionButton icon={RefreshCw} label="Recalcular liquidación" disabled={acting} onClick={() => void onAction(() => api.post(`/payroll/settlements/${settlement._id}/recalculate`, {}), 'Liquidación recalculada.')} /> : null}{canCalculate && ['draft', 'under_review'].includes(settlement.status) ? <TableActionButton icon={Trash2} label="Eliminar liquidación" disabled={acting} onClick={() => void onCancel(settlement)} /> : null}{canApprove && ['draft', 'under_review'].includes(settlement.status) ? <TableActionButton icon={Check} label="Aprobar liquidación" disabled={acting} onClick={() => void onAction(() => api.post(`/payroll/settlements/${settlement._id}/approve`, {}), 'Liquidación aprobada.')} /> : null}{canPay && settlement.status === 'approved' && settlement.paymentStatus !== 'paid' ? <TableActionButton icon={CircleDollarSign} label="Marcar liquidación como pagada" disabled={acting} onClick={() => void onAction(() => api.post(`/payroll/settlements/${settlement._id}/mark-paid`, {}), 'Pago registrado.')} /> : null}{canExport && settlement.status === 'approved' ? <TableActionButton icon={Download} label="Generar comprobante interno" disabled={acting} onClick={() => void onAction(async () => { const response = await api.post<{ receipt: { secureUrl?: string } }>(`/payroll/settlements/${settlement._id}/receipt`, {}); if (response.receipt.secureUrl) window.open(response.receipt.secureUrl, '_blank', 'noopener,noreferrer'); }, 'Comprobante generado.')} /> : null}</div></td></tr>)}</tbody></table>{!loading && !settlements.length ? <p className="p-8 text-center text-sm text-zinc-500">No hay liquidaciones para el período seleccionado.</p> : null}</div>;
}

function DataTable({ columns, rows, empty }: { columns: string[]; rows: Array<Array<ReactNode>>; empty: string }) { return <div className="overflow-x-auto rounded-2xl border border-zinc-200 bg-white shadow-sm"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500"><tr>{columns.map((column) => <th key={column} className="px-5 py-3">{column}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={index} className="border-t border-zinc-100">{row.map((cell, cellIndex) => <td key={cellIndex} className="px-5 py-3">{cell}</td>)}</tr>)}</tbody></table>{!rows.length ? <p className="p-8 text-center text-sm text-zinc-500">{empty}</p> : null}</div>; }

function Metric({ label, value }: { label: string; value: string }) { return <div><dt className="text-xs uppercase tracking-wide text-zinc-400">{label}</dt><dd className="mt-1 font-semibold text-zinc-900">{value}</dd></div>; }

function ConceptsView({ concepts, loading, canProfiles, onReload, showToast }: { concepts: Concept[]; loading: boolean; canProfiles: boolean; onReload: () => Promise<void>; showToast: ReturnType<typeof useToast>['showToast'] }) {
  const [form, setForm] = useState({ code: '', name: '', type: 'earning', source: 'manual', requiresReason: true });
  const [open, setOpen] = useState(false); const [saving, setSaving] = useState(false);
  async function save() { const parsed = z.object({ code: z.string().trim().min(2), name: z.string().trim().min(2) }).safeParse(form); if (!parsed.success) { showToast({ message: 'Completá código y nombre del concepto.', variant: 'error' }); return; } setSaving(true); try { await api.post('/payroll/concepts', { ...form, isAutomatic: false, isActive: true, displayOrder: concepts.length + 200 }); setOpen(false); await onReload(); showToast({ message: 'Concepto creado correctamente.', variant: 'success' }); } catch (error) { showToast({ message: apiError(error, 'No se pudo crear el concepto.'), variant: 'error' }); } finally { setSaving(false); } }
  return <div className="space-y-4"><div className="flex justify-end">{canProfiles ? <Button onClick={() => setOpen(true)}><Plus className="mr-2 h-4 w-4" />Nuevo concepto</Button> : null}</div><DataTable columns={['Código', 'Nombre', 'Tipo', 'Origen', 'Uso', 'Estado']} empty={loading ? 'Cargando conceptos…' : 'No hay conceptos configurados.'} rows={concepts.map((concept) => [concept.code, concept.name, concept.type === 'earning' ? 'Haber' : 'Descuento', concept.source, concept.isAutomatic ? 'Automático' : 'Manual', concept.isActive ? 'Activo' : 'Inactivo'])} /><Modal open={open} onClose={() => setOpen(false)} title="Nuevo concepto" description="Los conceptos utilizados se conservan históricamente; luego se pueden desactivar."><div className="space-y-4 p-6"><div className="grid gap-4 sm:grid-cols-2"><Field label="Código"><Input value={form.code} onChange={(event) => setForm((current) => ({ ...current, code: event.target.value.toUpperCase() }))} /></Field><Field label="Nombre"><Input value={form.name} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))} /></Field><Field label="Tipo"><Select value={form.type} onChange={(event) => setForm((current) => ({ ...current, type: event.target.value }))}><option value="earning">Haber</option><option value="deduction">Descuento</option></Select></Field><Field label="Origen"><Select value={form.source} onChange={(event) => setForm((current) => ({ ...current, source: event.target.value }))}><option value="manual">Manual</option><option value="bonus">Bonificación</option><option value="reimbursement">Viático / reintegro</option><option value="adjustment">Ajuste</option></Select></Field></div><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.requiresReason} onChange={(event) => setForm((current) => ({ ...current, requiresReason: event.target.checked }))} />Requerir motivo</label><footer className="flex justify-end gap-3"><Button variant="secondary" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving} onClick={() => void save()}>{saving ? 'Guardando…' : 'Crear concepto'}</Button></footer></div></Modal></div>;
}
